-- LANGKAH 1 — HAPUS SELURUH STRUKTUR DATABASE DAN BANGUN ULANG (satu lokasi: Salatiga)
-- Generated by npm run db:setup from supabase/reset/backup.sql, supabase/schema and
-- supabase/reset/restore.sql. Do not edit by hand. Jalankan seluruh isi file sekaligus di Supabase SQL Editor.
--
-- DIPERTAHANKAN: akun login (password tetap) dengan role Owner/Admin/Operator, waktu kerja, operator standar,
--   kecepatan desain, daftar mesin, link stok, dan nomor Customer Service.
--   Dari database cabang lama hanya akun dan pengaturan Salatiga yang dipertahankan; akun Owner Pusat dan
--   akun cabang lain dihapus.
-- DIHAPUS PERMANEN: semua order, customer, riwayat, laporan, catatan Mulai/Selesai, jam operator, serta
--   seluruh tabel, fungsi dan aturan lama di skema public.
-- Aman dijalankan ulang, juga bila percobaan sebelumnya terhenti di tengah. Dibatalkan tanpa perubahan bila
-- tidak ada akun Owner aktif yang ikut dipertahankan. Setelah selesai, semua pengguna perlu me-refresh halaman.

-- ===== Bagian 1: simpan akun & pengaturan, lalu kosongkan skema public =====
-- Bekerja dari kondisi apa pun: database cabang lama (hanya Salatiga dipertahankan), database lama
-- tanpa cabang, database satu lokasi yang sudah ada, atau reset sebelumnya yang terhenti di tengah.
DO $$
DECLARE salatiga uuid; owners integer; had_profiles boolean;
BEGIN
 had_profiles := to_regclass('public.profiles') IS NOT NULL;
 IF NOT had_profiles AND to_regnamespace('printex_keep') IS NOT NULL THEN
  -- Reset sebelumnya terhenti setelah bagian 1: pakai cadangan yang sudah ada.
  RAISE NOTICE 'Melanjutkan reset sebelumnya dengan cadangan yang sudah tersimpan.';
 ELSE
  DROP SCHEMA IF EXISTS printex_keep CASCADE;
  CREATE SCHEMA printex_keep;
  CREATE TABLE printex_keep.profiles (id uuid, full_name text, role text, is_active boolean);
  CREATE TABLE printex_keep.settings (shifts smallint, shift_hours numeric, planned_downtime_minutes integer,
   operators_printing smallint, operators_dtf smallint, operators_press smallint, operators_design smallint, design_orders_per_hour numeric);
  CREATE TABLE printex_keep.machines (kind text, name text, created_at timestamptz);
  CREATE TABLE printex_keep.stock_shortcuts (id text, label text, url text);
  CREATE TABLE printex_keep.customer_service (whatsapp_number text);

  IF to_regclass('public.branches') IS NOT NULL THEN
   -- Database cabang lama: hanya akun dan pengaturan Salatiga yang dipertahankan.
   EXECUTE 'SELECT id FROM public.branches WHERE name=''Salatiga''' INTO salatiga;
   IF salatiga IS NULL THEN RAISE EXCEPTION 'Cabang Salatiga tidak ditemukan.'; END IF;
   EXECUTE 'INSERT INTO printex_keep.profiles SELECT p.id,p.full_name,p.role,p.is_active FROM public.profiles p JOIN auth.users u ON u.id=p.id
    WHERE p.branch_id=$1 AND p.role IN (''owner'',''admin'',''operator'') AND u.deleted_at IS NULL AND p.deletion_requested_at IS NULL' USING salatiga;
   IF to_regclass('public.branch_production_capacity') IS NOT NULL THEN
    EXECUTE 'INSERT INTO printex_keep.settings SELECT shifts,shift_hours,planned_downtime_minutes,operators_printing,operators_dtf,operators_press,operators_design,design_orders_per_hour
     FROM public.branch_production_capacity WHERE branch_id=$1' USING salatiga;
   END IF;
   IF to_regclass('public.branch_machines') IS NOT NULL THEN
    EXECUTE 'INSERT INTO printex_keep.machines SELECT kind,name,created_at FROM public.branch_machines WHERE branch_id=$1 AND removed_at IS NULL' USING salatiga;
   END IF;
   IF to_regclass('public.branch_stock_shortcuts') IS NOT NULL THEN
    EXECUTE 'INSERT INTO printex_keep.stock_shortcuts SELECT id,label,url FROM public.branch_stock_shortcuts WHERE branch_id=$1' USING salatiga;
   END IF;
  ELSIF had_profiles THEN
   -- Database tanpa cabang (lama atau satu lokasi): semua akun ikut; nama role lama dikonversi.
   EXECUTE 'INSERT INTO printex_keep.profiles SELECT p.id,p.full_name,CASE p.role WHEN ''superadmin'' THEN ''owner'' WHEN ''staff'' THEN ''operator'' ELSE p.role END,p.is_active
    FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.role IN (''owner'',''admin'',''operator'',''superadmin'',''staff'') AND u.deleted_at IS NULL';
   IF to_regclass('public.production_settings') IS NOT NULL THEN
    EXECUTE 'INSERT INTO printex_keep.settings SELECT shifts,shift_hours,planned_downtime_minutes,operators_printing,operators_dtf,operators_press,operators_design,design_orders_per_hour FROM public.production_settings';
   END IF;
   IF to_regclass('public.production_machines') IS NOT NULL THEN
    EXECUTE 'INSERT INTO printex_keep.machines SELECT kind,name,created_at FROM public.production_machines WHERE removed_at IS NULL';
   END IF;
   IF to_regclass('public.stock_shortcuts') IS NOT NULL THEN
    EXECUTE 'INSERT INTO printex_keep.stock_shortcuts SELECT id,label,url FROM public.stock_shortcuts';
   END IF;
  END IF;
  IF to_regclass('public.customer_service_settings') IS NOT NULL THEN
   EXECUTE 'INSERT INTO printex_keep.customer_service SELECT whatsapp_number FROM public.customer_service_settings LIMIT 1';
  END IF;

  -- Pengaman: jangan sampai tidak ada yang bisa login sebagai Owner.
  SELECT count(*) INTO owners FROM printex_keep.profiles WHERE role='owner' AND is_active;
  IF had_profiles AND owners = 0 THEN
   RAISE EXCEPTION 'Tidak ada akun Owner aktif yang ikut disimpan. Jadikan satu akun sebagai Owner (Salatiga) dulu di Pusat Admin → Akun, lalu jalankan reset lagi. Tidak ada yang diubah.';
  END IF;
  -- Akun yang tidak ikut ke Salatiga (Owner Pusat dan akun cabang lain) dihapus loginnya.
  CREATE TABLE printex_keep.removed_users (id uuid);
  IF had_profiles THEN
   EXECUTE 'INSERT INTO printex_keep.removed_users SELECT p.id FROM public.profiles p WHERE p.id NOT IN (SELECT id FROM printex_keep.profiles)';
  END IF;
 END IF;

 -- Kosongkan skema public dan siapkan lagi hak akses standar Supabase.
 DROP SCHEMA IF EXISTS public CASCADE;
 CREATE SCHEMA public;
 GRANT USAGE ON SCHEMA public TO PUBLIC;
 PERFORM 1 FROM pg_roles WHERE rolname='service_role';
 IF FOUND THEN
  EXECUTE 'GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role';
  EXECUTE 'GRANT ALL ON SCHEMA public TO service_role';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON FUNCTIONS TO anon, authenticated, service_role';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO anon, authenticated, service_role';
 ELSE
  EXECUTE 'GRANT USAGE ON SCHEMA public TO anon, authenticated';
 END IF;
 DELETE FROM auth.users WHERE id IN (SELECT id FROM printex_keep.removed_users);
END $$;

-- ===== Bagian 2: bangun seluruh struktur database =====
BEGIN;
DO $$ BEGIN
 IF to_regclass('public.orders') IS NOT NULL THEN
  RAISE EXCEPTION 'Database sudah berisi tabel Printex. Jalankan supabase/manual/1_RESET_STRUKTUR_DATABASE.sql untuk membangun ulang.';
 END IF;
END $$;
-- supabase/schema/01_akun.sql
-- Akun karyawan: profil per login Supabase Auth, peran Owner/Admin/Operator, dan pengelolaan akun oleh Owner.
CREATE TABLE public.profiles (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  full_name text NOT NULL,
  role text NOT NULL DEFAULT 'operator' CHECK (role IN ('owner','admin','operator')),
  is_active boolean NOT NULL DEFAULT false,
  deletion_requested_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- Karyawan aktif (semua peran) dan pengelola (Owner/Admin). Dipakai oleh RLS dan RPC.
CREATE FUNCTION public.printex_staff() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active AND role IN ('owner','admin','operator'));
$$;
CREATE FUNCTION public.printex_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active AND role IN ('owner','admin'));
$$;

CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated
  USING (id=auth.uid() OR public.printex_admin());

-- Login baru selalu menjadi Operator nonaktif sampai diaktifkan Owner (metadata pendaftar diabaikan).
CREATE FUNCTION public.printex_new_profile() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  INSERT INTO public.profiles(id,full_name,role,is_active)
  VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.email,'Karyawan'),'operator',false)
  ON CONFLICT(id) DO NOTHING;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS printex_auth_profile ON auth.users;
CREATE TRIGGER printex_auth_profile AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.printex_new_profile();

CREATE FUNCTION public.printex_list_users()
RETURNS TABLE(id uuid, email text, full_name text, role text, is_active boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.is_active AND p.role='owner') THEN
    RAISE EXCEPTION 'Hanya Owner yang dapat mengelola akun' USING ERRCODE='42501';
  END IF;
  -- Akun yang penghapusannya belum selesai tetap tampil agar bisa dicoba hapus lagi.
  RETURN QUERY SELECT p.id,u.email::text,p.full_name,p.role,p.is_active
    FROM public.profiles p JOIN auth.users u ON u.id=p.id
    WHERE u.deleted_at IS NULL OR p.deletion_requested_at IS NOT NULL
    ORDER BY p.created_at,p.id;
END $$;

-- Ubah nama/peran/status, atau tandai untuk dihapus (login dihapus server lewat Auth Admin API).
CREATE FUNCTION public.printex_manage_user(p_id uuid, p_name text, p_role text, p_active boolean, p_delete boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE target public.profiles;
BEGIN
  -- Serialisasi agar dua perubahan bersamaan tidak menghapus Owner terakhir.
  PERFORM pg_advisory_xact_lock(hashtextextended('printex-user-management',0));
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active AND role='owner') THEN
    RAISE EXCEPTION 'Hanya Owner yang dapat mengelola akun' USING ERRCODE='42501';
  END IF;
  SELECT * INTO target FROM public.profiles WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Akun tidak ditemukan'; END IF;
  IF p_id=auth.uid() AND (p_delete OR p_active IS DISTINCT FROM true OR p_role IS DISTINCT FROM 'owner') THEN
    RAISE EXCEPTION 'Tidak dapat menghapus, menonaktifkan, atau menurunkan role akun sendiri';
  END IF;
  IF target.role='owner' AND target.is_active AND (p_delete OR p_active IS DISTINCT FROM true OR p_role IS DISTINCT FROM 'owner')
    AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE role='owner' AND is_active AND id<>p_id) THEN
    RAISE EXCEPTION 'Minimal satu Owner aktif harus tersedia';
  END IF;
  IF p_delete THEN
    UPDATE public.profiles SET is_active=false,deletion_requested_at=now(),updated_at=now() WHERE id=p_id;
    RETURN;
  END IF;
  IF target.deletion_requested_at IS NOT NULL THEN
    RAISE EXCEPTION 'Penghapusan akun sedang diproses. Selesaikan penghapusan terlebih dahulu';
  END IF;
  IF nullif(trim(p_name),'') IS NULL OR length(p_name)>100 OR p_role IS NULL
     OR p_role NOT IN ('owner','admin','operator') OR p_active IS NULL THEN
    RAISE EXCEPTION 'Nama, role, atau status akun tidak valid';
  END IF;
  IF EXISTS(SELECT 1 FROM auth.users WHERE id=p_id AND deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Akun sudah dihapus'; END IF;
  UPDATE public.profiles SET full_name=trim(p_name),role=p_role,is_active=p_active,updated_at=now() WHERE id=p_id;
END $$;

-- supabase/schema/02_master_produksi.sql
-- Data induk produksi: tahap board, mesin, serta waktu kerja dan operator standar (satu lokasi: Salatiga).

-- ===== Tahap board =====
-- DESIGN boleh dilewati (Order Masuk -> Menunggu Pembayaran); DTF boleh melewati Press.
-- ARCHIVE = "Order Diterima Customer"; laporan arsip dihitung dari kolom arsip pada orders.
CREATE TABLE public.production_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  sequence integer NOT NULL UNIQUE
);
INSERT INTO public.production_steps(code,name,sequence) VALUES
  ('ORDER_IN','Order Masuk',1),
  ('DESIGN','Proses Desain',2),
  ('DESIGN_DONE','Menunggu Pembayaran',3),
  ('PRINTING','Proses Sublim',4),
  ('PRESS','Proses Press',5),
  ('DONE','Order Selesai',6),
  ('ARCHIVE','Order Diterima Customer',7);
ALTER TABLE public.production_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_steps_read ON public.production_steps FOR SELECT TO authenticated USING (public.printex_staff());

-- ===== Mesin =====
-- Fedar mencetak Sublim (semua jenis selain DTF), DTF mencetak DTF, Press mengepres lini Sublim.
-- Penghapusan bersifat lunak agar order lama tetap menunjuk mesinnya.
CREATE TABLE public.production_machines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind text NOT NULL CHECK (kind IN ('fedar','dtf','press')),
  name text NOT NULL CHECK (length(name) BETWEEN 1 AND 40 AND name=btrim(name)),
  created_at timestamptz NOT NULL DEFAULT now(),
  removed_at timestamptz
);
CREATE UNIQUE INDEX production_machines_active_name ON public.production_machines(lower(name)) WHERE removed_at IS NULL;
INSERT INTO public.production_machines(kind,name) VALUES
  ('fedar','Fedar 1'),('fedar','Fedar 2'),('dtf','DTF 1'),('press','Press 1');
ALTER TABLE public.production_machines ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_machines_read ON public.production_machines FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY production_machines_insert ON public.production_machines FOR INSERT TO authenticated WITH CHECK (public.printex_admin());
CREATE POLICY production_machines_update ON public.production_machines FOR UPDATE TO authenticated
  USING (public.printex_admin()) WITH CHECK (public.printex_admin());

-- ===== Waktu kerja dan operator standar (satu baris) =====
-- Jam tersedia = shift x jam per shift; jam efektif (T) = jam tersedia - istirahat & setup.
-- Standar: 1 shift 9 jam, istirahat 1,5 jam + briefing/setup 30 menit (T = 7 jam).
-- Operator standar: Fedar 1 per mesin (2), DTF 1 per mesin (1), Press 3 per mesin (3), desain 1.
CREATE TABLE public.production_settings (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  shifts smallint NOT NULL DEFAULT 1 CHECK (shifts BETWEEN 1 AND 3),
  shift_hours numeric(4,2) NOT NULL DEFAULT 9 CHECK (shift_hours > 0 AND shift_hours <= 24),
  planned_downtime_minutes integer NOT NULL DEFAULT 120 CHECK (planned_downtime_minutes BETWEEN 0 AND 1440),
  effective_hours numeric(4,2) NOT NULL DEFAULT 7 CHECK (effective_hours > 0 AND effective_hours <= 24),
  operators_printing smallint NOT NULL DEFAULT 2 CHECK (operators_printing BETWEEN 0 AND 50),
  operators_dtf smallint NOT NULL DEFAULT 1 CHECK (operators_dtf BETWEEN 0 AND 50),
  operators_press smallint NOT NULL DEFAULT 3 CHECK (operators_press BETWEEN 0 AND 50),
  operators_design smallint NOT NULL DEFAULT 1 CHECK (operators_design BETWEEN 0 AND 50),
  -- Desain dihitung per order, bukan per meter (opsional): kapasitas desain = order/jam x T.
  design_orders_per_hour numeric(6,2) CHECK (design_orders_per_hour > 0 AND design_orders_per_hour <= 1000),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0)
);
CREATE FUNCTION public.printex_working_hours() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  NEW.effective_hours := round(NEW.shifts*NEW.shift_hours - NEW.planned_downtime_minutes/60.0, 2);
  IF NEW.shifts*NEW.shift_hours > 24 THEN RAISE EXCEPTION 'Jam kerja tersedia maksimal 24 jam per hari'; END IF;
  IF NEW.effective_hours <= 0 THEN RAISE EXCEPTION 'Istirahat & setup harus lebih kecil dari jam kerja tersedia'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER working_hours BEFORE INSERT OR UPDATE ON public.production_settings
  FOR EACH ROW EXECUTE FUNCTION public.printex_working_hours();
INSERT INTO public.production_settings(singleton) VALUES (true);
ALTER TABLE public.production_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_settings_read ON public.production_settings FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY production_settings_write ON public.production_settings FOR UPDATE TO authenticated
  USING (public.printex_admin()) WITH CHECK (public.printex_admin());

-- supabase/schema/03_order.sql
-- Order, customer, dan riwayat proses. Semua perubahan order lewat printex_mutate_order (SECURITY DEFINER);
-- karyawan hanya bisa membaca tabel secara langsung.

CREATE TABLE public.customers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  phone text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Nomor SPK otomatis bila SPK tidak diisi saat membuat order.
CREATE SEQUENCE public.printex_spk_seq START 1100;

CREATE TABLE public.orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  spk_code text NOT NULL UNIQUE,
  customer_id uuid NOT NULL REFERENCES public.customers(id),
  production_type text NOT NULL,
  meter numeric(10,2) NOT NULL DEFAULT 0 CHECK (meter >= 0),
  -- Lebar kertas (meter): DTF selalu 0,6; produksi lain 1,2 / 1,6 / 1,8 atau belum diisi.
  paper_width numeric CHECK (paper_width IS NULL
    OR (production_type='DTF' AND paper_width=0.6)
    OR (production_type<>'DTF' AND paper_width IN (1.2,1.6,1.8))),
  customer_type text NOT NULL DEFAULT 'regular' CHECK (customer_type IN ('regular','priority')),
  current_step_id uuid NOT NULL REFERENCES public.production_steps(id),
  order_state text NOT NULL DEFAULT 'active' CHECK (order_state IN ('active','completed')),
  print_machine_id uuid REFERENCES public.production_machines(id),
  order_date date NOT NULL,
  due_at date,
  notes text NOT NULL DEFAULT '',
  photo_path text,
  -- 'simulation' menandai data uji (supabase/manual/2_DATA_UJI_7_HARI.sql).
  source text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','simulation')),
  archived_at timestamptz,
  delivery_method text CHECK (delivery_method IN ('pickup','delivery','received')),
  archive_finalized_at timestamptz,
  version bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT archive_delivery_metadata CHECK ((archived_at IS NULL) = (delivery_method IS NULL)),
  CONSTRAINT finalized_requires_archive CHECK (archive_finalized_at IS NULL OR archived_at IS NOT NULL)
);
CREATE INDEX orders_customer ON public.orders(customer_id);
CREATE INDEX orders_current_step ON public.orders(current_step_id);
CREATE INDEX orders_order_date ON public.orders(order_date);
CREATE INDEX orders_finalized_at ON public.orders(archive_finalized_at);
CREATE INDEX orders_photo_path ON public.orders(photo_path) WHERE photo_path IS NOT NULL;
CREATE INDEX orders_print_machine ON public.orders(print_machine_id) WHERE print_machine_id IS NOT NULL;

-- Riwayat ringkas: satu baris 'entered' saat order dibuat, lalu satu baris per perpindahan
-- (tahap yang ditinggalkan + tahap tujuan di next_step_id). Riwayat tetap ada bila order dihapus.
CREATE TABLE public.process_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL,
  order_identity text NOT NULL,
  spk_code text NOT NULL,
  customer_name text NOT NULL DEFAULT '',
  step_id uuid NOT NULL REFERENCES public.production_steps(id),
  event_kind text NOT NULL CHECK (event_kind IN ('entered','completed','returned')),
  next_step_id uuid REFERENCES public.production_steps(id),
  next_event_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX process_history_order ON public.process_history(order_id);
CREATE INDEX process_history_scope_page ON public.process_history(order_identity, id);
CREATE INDEX process_history_scope_time ON public.process_history(occurred_at, order_identity);

-- order_identity menyimpan ID order secara permanen (order_id menjadi NULL bila order dihapus).
CREATE FUNCTION public.set_process_order_identity() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  NEW.order_identity := NEW.order_id::text;
  RETURN NEW;
END $$;
CREATE TRIGGER process_history_set_identity BEFORE INSERT ON public.process_history
  FOR EACH ROW EXECUTE FUNCTION public.set_process_order_identity();

ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.process_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY customers_read ON public.customers FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY orders_read ON public.orders FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY process_history_read ON public.process_history FOR SELECT TO authenticated USING (public.printex_staff());

-- ===== Aturan order (urutan trigger BEFORE mengikuti abjad: 00_defaults, adjacent_stage, enforce_archiving) =====
-- printex.importing='yes' hanya dipakai skrip data uji untuk menulis riwayat dengan waktu lampau.

-- Tahap awal, status, waktu ubah, dan versi untuk penguncian optimistis.
CREATE FUNCTION public.printex_order_defaults() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE step_code text;
BEGIN
  IF current_setting('printex.importing',true)='yes' THEN RETURN NEW; END IF;
  IF TG_OP='INSERT' THEN
    SELECT id INTO NEW.current_step_id FROM public.production_steps WHERE code='ORDER_IN';
  END IF;
  SELECT code INTO STRICT step_code FROM public.production_steps WHERE id=NEW.current_step_id;
  NEW.order_state := CASE WHEN step_code IN ('DONE','ARCHIVE') THEN 'completed' ELSE 'active' END;
  NEW.updated_at := statement_timestamp();
  IF TG_OP='UPDATE' THEN NEW.version := OLD.version+1; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER orders_00_defaults BEFORE INSERT OR UPDATE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.printex_order_defaults();

-- Order hanya pindah ke tahap sebelah, kecuali melewati desain atau DTF melewati Press.
CREATE FUNCTION public.enforce_adjacent_order_stage() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_code text; next_code text; previous_position integer; next_position integer;
BEGIN
  IF OLD.current_step_id IS NOT DISTINCT FROM NEW.current_step_id THEN RETURN NEW; END IF;
  SELECT code,sequence INTO previous_code,previous_position FROM public.production_steps WHERE id=OLD.current_step_id;
  SELECT code,sequence INTO next_code,next_position FROM public.production_steps WHERE id=NEW.current_step_id;
  IF previous_code='ORDER_IN' AND next_code='DESIGN_DONE' THEN RETURN NEW; END IF;
  IF previous_code='PRINTING' AND next_code='DONE' AND NEW.production_type='DTF' THEN RETURN NEW; END IF;
  IF previous_position IS NULL OR next_position IS NULL OR abs(next_position-previous_position)<>1 THEN
    RAISE EXCEPTION 'Orders can only move to the previous or next stage, skip design, or skip Press for DTF';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER orders_adjacent_stage BEFORE UPDATE OF current_step_id ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.enforce_adjacent_order_stage();

-- Arsip: hanya order Selesai dengan konfirmasi penyerahan; order arsip hanya bisa difinalisasi sekali
-- dan tidak bisa diubah atau dihapus. 'received' langsung final. Foto dilepas saat final.
CREATE FUNCTION public.enforce_order_archiving() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_code text; next_code text;
BEGIN
  IF current_setting('printex.importing',true)='yes' THEN RETURN NEW; END IF;
  IF TG_OP<>'INSERT' THEN
    SELECT code INTO previous_code FROM public.production_steps WHERE id=OLD.current_step_id;
    IF previous_code='ARCHIVE' THEN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Preserve archived orders and reports'; END IF;
      IF (to_jsonb(NEW)-'archive_finalized_at'-'updated_at'-'version')
         IS DISTINCT FROM (to_jsonb(OLD)-'archive_finalized_at'-'updated_at'-'version') THEN
        RAISE EXCEPTION 'Archived order data is read-only';
      END IF;
      IF OLD.archive_finalized_at IS NOT NULL THEN
        RETURN OLD; -- klik berulang tidak mengubah tanggal laporan asli
      END IF;
      IF NEW.archive_finalized_at IS NOT NULL THEN
        NEW.archive_finalized_at := statement_timestamp();
        NEW.photo_path := NULL;
      END IF;
      RETURN NEW;
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF NEW.archive_finalized_at IS NOT NULL THEN RAISE EXCEPTION 'Move to the archive board before finalizing'; END IF;
  SELECT code INTO next_code FROM public.production_steps WHERE id=NEW.current_step_id;
  IF next_code='ARCHIVE' THEN
    IF TG_OP='INSERT' OR previous_code IS DISTINCT FROM 'DONE' THEN RAISE EXCEPTION 'Only Done orders can be archived'; END IF;
    IF NEW.delivery_method IS NULL THEN RAISE EXCEPTION 'Confirm pickup or delivery before archiving'; END IF;
    NEW.archived_at := statement_timestamp();
    IF NEW.delivery_method='received' THEN
      NEW.archive_finalized_at := NEW.archived_at;
      NEW.photo_path := NULL;
    END IF;
    NEW.order_state := 'completed';
  ELSIF NEW.archived_at IS NOT NULL OR NEW.delivery_method IS NOT NULL THEN
    RAISE EXCEPTION 'Delivery metadata is only valid for archived orders';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER orders_enforce_archiving BEFORE INSERT OR UPDATE OR DELETE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.enforce_order_archiving();

-- Riwayat proses dicatat otomatis saat order dibuat dan setiap pindah tahap.
CREATE FUNCTION public.capture_process_history() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_sequence integer; next_sequence integer; customer text;
BEGIN
  IF current_setting('printex.importing',true)='yes' THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.current_step_id IS NOT DISTINCT FROM NEW.current_step_id THEN RETURN NEW; END IF;
  SELECT sequence INTO STRICT next_sequence FROM public.production_steps WHERE id=NEW.current_step_id;
  SELECT name INTO customer FROM public.customers WHERE id=NEW.customer_id;
  IF TG_OP='UPDATE' THEN
    SELECT sequence INTO STRICT previous_sequence FROM public.production_steps WHERE id=OLD.current_step_id;
    INSERT INTO public.process_history(order_id,spk_code,step_id,event_kind,customer_name,next_step_id,next_event_id,occurred_at)
    VALUES(NEW.id,NEW.spk_code,OLD.current_step_id,
      CASE WHEN next_sequence>previous_sequence THEN 'completed' ELSE 'returned' END,
      coalesce(customer,''),NEW.current_step_id,gen_random_uuid(),statement_timestamp());
  ELSE
    INSERT INTO public.process_history(order_id,spk_code,step_id,event_kind,customer_name,occurred_at)
    VALUES(NEW.id,NEW.spk_code,NEW.current_step_id,'entered',coalesce(customer,''),statement_timestamp());
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER orders_capture_process_history AFTER INSERT OR UPDATE OF current_step_id ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.capture_process_history();

-- ===== Semua perubahan order =====
-- Owner/Admin: create, edit, move, delete, archive, finish. Operator: hanya move di antara
-- Menunggu Pembayaran, Sublim, Press, dan Order Selesai.
CREATE FUNCTION public.printex_mutate_order(p_action text, p_order_id uuid, p_expected_version bigint, p_data jsonb DEFAULT '{}'::jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; customer_uuid uuid; stage_uuid uuid; actor_role text; source_code text;
BEGIN
  -- Profil dikunci sampai commit, termasuk terhadap perubahan peran bersamaan.
  SELECT p.role INTO actor_role FROM public.profiles p
    WHERE p.id=auth.uid() AND p.is_active AND p.role IN ('owner','admin','operator') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('create','edit','move','delete','archive','finish') THEN RAISE EXCEPTION 'Aksi tidak valid'; END IF;
  IF actor_role='operator' AND p_action<>'move' THEN
    RAISE EXCEPTION 'Operator tidak dapat menambah, mengedit, menghapus, atau mengarsipkan order' USING ERRCODE='42501';
  END IF;

  IF p_action IN ('create','edit') THEN
    IF p_data->>'productionType'='DTF' THEN p_data := jsonb_set(p_data,'{paperWidth}','"0.6"'::jsonb); END IF;
    IF p_data->>'paperWidth' IS NOT NULL AND p_data->>'productionType'<>'DTF'
       AND p_data->>'paperWidth' NOT IN ('1.2','1.6','1.8') THEN
      RAISE EXCEPTION 'Lebar kertas untuk semua produksi selain DTF: pilih 1,2, 1,6, atau 1,8 meter';
    END IF;
    IF length(trim(p_data->>'customerPhone'))>30 THEN RAISE EXCEPTION 'Nomor WhatsApp maksimal 30 karakter'; END IF;
    IF nullif(trim(p_data->>'customerName'),'') IS NULL OR length(p_data->>'customerName')>200
       OR p_data->>'productionType' IS NULL OR p_data->>'productionType' NOT IN ('Sublim','DTF','Umbul-umbul','Batik','Jersey')
       OR p_data->>'meter' IS NULL OR (p_data->>'meter')::numeric<0
       OR p_data->>'customerType' IS NULL OR p_data->>'customerType' NOT IN ('regular','priority')
       OR nullif(p_data->>'orderDate','') IS NULL OR nullif(p_data->>'dueDate','') IS NULL THEN
      RAISE EXCEPTION 'Data order tidak lengkap atau tidak valid';
    END IF;
  END IF;

  IF p_action='create' THEN
    IF p_data ? 'spkCode' AND nullif(trim(p_data->>'spkCode'),'') IS NULL THEN RAISE EXCEPTION 'Kode SPK wajib diisi'; END IF;
    -- UUID dari klien membuat pengiriman ulang setelah respons hilang tetap aman.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_order_id::text,0));
    IF EXISTS(SELECT 1 FROM public.orders WHERE id=p_order_id) THEN RETURN p_order_id; END IF;
    INSERT INTO public.customers(name,phone)
      VALUES(trim(p_data->>'customerName'),nullif(trim(p_data->>'customerPhone'),'')) RETURNING id INTO customer_uuid;
    INSERT INTO public.orders(id,spk_code,customer_id,production_type,meter,paper_width,customer_type,order_date,due_at,notes)
    VALUES(p_order_id,coalesce(nullif(trim(p_data->>'spkCode'),''),'SPK-'||nextval('public.printex_spk_seq')),customer_uuid,
      p_data->>'productionType',(p_data->>'meter')::numeric,(p_data->>'paperWidth')::numeric,p_data->>'customerType',
      (p_data->>'orderDate')::date,(p_data->>'dueDate')::date,coalesce(p_data->>'notes',''));
    RETURN p_order_id;
  END IF;

  SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order sudah dihapus atau tidak ditemukan'; END IF;
  IF actor_role='operator' THEN
    SELECT code INTO source_code FROM public.production_steps WHERE id=o.current_step_id;
    IF source_code IS NULL OR source_code NOT IN ('DESIGN_DONE','PRINTING','PRESS','DONE')
       OR coalesce(p_data->>'code','') NOT IN ('DESIGN_DONE','PRINTING','PRESS','DONE') THEN
      RAISE EXCEPTION 'Operator hanya dapat memindahkan order antara Menunggu Pembayaran, Sublim, Press, dan Order Selesai' USING ERRCODE='42501';
    END IF;
  END IF;
  IF p_action='finish' AND o.archive_finalized_at IS NOT NULL THEN RETURN o.id; END IF;
  IF o.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'Order sudah diubah perangkat lain. Muat ulang dan coba lagi.' USING ERRCODE='40001';
  END IF;
  CASE p_action
  WHEN 'edit' THEN
    IF nullif(trim(p_data->>'spkCode'),'') IS NULL THEN RAISE EXCEPTION 'Kode SPK wajib diisi'; END IF;
    UPDATE public.customers SET name=trim(p_data->>'customerName'),
      phone=CASE WHEN p_data ? 'customerPhone' THEN nullif(trim(p_data->>'customerPhone'),'') ELSE phone END,
      updated_at=statement_timestamp() WHERE id=o.customer_id;
    -- Klien lama tanpa paperWidth mempertahankan lebar yang tersimpan.
    UPDATE public.orders SET spk_code=trim(p_data->>'spkCode'),production_type=p_data->>'productionType',meter=(p_data->>'meter')::numeric,
      paper_width=CASE WHEN p_data->>'productionType'='DTF' THEN 0.6
        WHEN p_data ? 'paperWidth' THEN (p_data->>'paperWidth')::numeric
        WHEN o.paper_width=0.6 THEN NULL ELSE o.paper_width END,
      customer_type=p_data->>'customerType',order_date=(p_data->>'orderDate')::date,due_at=(p_data->>'dueDate')::date,
      notes=coalesce(p_data->>'notes','') WHERE id=o.id;
  WHEN 'move' THEN
    IF p_data->>'code'='ARCHIVE' THEN RAISE EXCEPTION 'Konfirmasi penyerahan sebelum arsip'; END IF;
    SELECT id INTO STRICT stage_uuid FROM public.production_steps WHERE code=p_data->>'code';
    UPDATE public.orders SET current_step_id=stage_uuid WHERE id=o.id;
  WHEN 'archive' THEN
    SELECT id INTO STRICT stage_uuid FROM public.production_steps WHERE code='ARCHIVE';
    UPDATE public.orders SET current_step_id=stage_uuid,delivery_method=p_data->>'deliveryMethod' WHERE id=o.id;
  WHEN 'finish' THEN
    UPDATE public.orders SET archive_finalized_at=statement_timestamp() WHERE id=o.id;
  WHEN 'delete' THEN
    DELETE FROM public.orders WHERE id=o.id;
  END CASE;
  RETURN o.id;
END $$;

-- Mesin cetak order; bisa sekaligus memindahkan order ke Proses Sublim dalam satu transaksi
-- (perpindahan memakai printex_mutate_order dan seluruh aturannya).
CREATE FUNCTION public.printex_set_print_machine(p_order uuid, p_expected_version bigint, p_machine uuid, p_move boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; m public.production_machines; step text; required text;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF;
  SELECT * INTO m FROM public.production_machines WHERE id=p_machine AND removed_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Mesin tidak tersedia'; END IF;
  required := CASE WHEN upper(btrim(o.production_type))='DTF' THEN 'dtf' ELSE 'fedar' END;
  IF m.kind<>required THEN RAISE EXCEPTION 'Order DTF hanya dapat dicetak di mesin DTF; bahan lain di mesin Fedar'; END IF;
  IF p_move THEN
    PERFORM public.printex_mutate_order('move',p_order,p_expected_version,jsonb_build_object('code','PRINTING'));
  ELSIF o.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'Order telah diubah oleh pengguna lain. Muat ulang lalu coba kembali.' USING ERRCODE='40001';
  END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE;
  SELECT code INTO step FROM public.production_steps WHERE id=o.current_step_id;
  IF step IS DISTINCT FROM 'PRINTING' THEN RAISE EXCEPTION 'Mesin hanya dapat dipilih saat order berada di Proses Sublim'; END IF;
  IF o.print_machine_id IS DISTINCT FROM p_machine THEN UPDATE public.orders SET print_machine_id=p_machine WHERE id=p_order; END IF;
END $$;

-- supabase/schema/04_sinkronisasi.sql
-- Pemuatan dashboard: snapshot per periode dan sinkronisasi bertahap (hanya ID baris yang berubah).

-- Jam revisi global + revisi terakhir per baris. Baris yang dihapus tetap dicatat agar klien membuangnya.
CREATE TABLE public.printex_sync_clock (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  revision bigint NOT NULL DEFAULT 0
);
INSERT INTO public.printex_sync_clock(singleton) VALUES (true);
CREATE TABLE public.printex_row_changes (
  table_name text NOT NULL,
  row_id uuid NOT NULL,
  revision bigint NOT NULL,
  deleted boolean NOT NULL,
  PRIMARY KEY (table_name,row_id)
);
CREATE INDEX printex_row_changes_revision ON public.printex_row_changes(revision);
ALTER TABLE public.printex_sync_clock ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.printex_row_changes ENABLE ROW LEVEL SECURITY;

CREATE FUNCTION public.printex_record_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rev bigint; item jsonb;
BEGIN
  -- Kunci baris jam ditahan sampai commit: kursor tidak bisa melewati transaksi yang commit belakangan.
  UPDATE public.printex_sync_clock SET revision=revision+1 WHERE singleton RETURNING revision INTO rev;
  item := CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  INSERT INTO public.printex_row_changes VALUES(TG_TABLE_NAME,(item->>'id')::uuid,rev,TG_OP='DELETE')
  ON CONFLICT(table_name,row_id) DO UPDATE SET revision=excluded.revision,deleted=excluded.deleted;
  RETURN NULL;
END $$;
CREATE TRIGGER printex_track_change AFTER INSERT OR UPDATE OR DELETE ON public.production_steps
  FOR EACH ROW EXECUTE FUNCTION public.printex_record_change();
CREATE TRIGGER printex_track_change AFTER INSERT OR UPDATE OR DELETE ON public.customers
  FOR EACH ROW EXECUTE FUNCTION public.printex_record_change();
CREATE TRIGGER printex_track_change AFTER INSERT OR UPDATE OR DELETE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.printex_record_change();
CREATE TRIGGER printex_track_change AFTER INSERT OR UPDATE OR DELETE ON public.process_history
  FOR EACH ROW EXECUTE FUNCTION public.printex_record_change();

-- Kursor dan perubahan dibaca dalam satu snapshot. Lebih dari 2000 perubahan = klien memuat ulang penuh.
CREATE FUNCTION public.printex_sync_changes(p_after bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
  WITH delta AS (
    SELECT d.table_name,d.row_id FROM public.printex_row_changes d
    WHERE p_after IS NOT NULL AND d.revision>p_after LIMIT 2001
  ), summary AS (SELECT count(*) AS n FROM delta)
  SELECT jsonb_build_object('cursor',c.revision::text,'reset',summary.n>2000,'changes',
    CASE WHEN p_after IS NULL OR summary.n>2000 THEN '[]'::jsonb
    ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('table',d.table_name,'id',d.row_id)) FROM delta d),'[]'::jsonb) END)
  INTO result FROM public.printex_sync_clock c CROSS JOIN summary WHERE singleton;
  RETURN result;
END $$;

-- Data dashboard untuk satu periode: order aktif, order yang masuk/selesai di periode, order yang
-- diminta (p_order), dan riwayat lengkap order-order itu. Riwayat tahap arsip tidak dikirim.
-- p_changes membatasi ke baris yang berubah; riwayat dibagi per halaman 5000 baris
-- (p_history_after + p_history_ids, p_history_only melewati order/customer/tahap).
-- SECURITY INVOKER: RLS tabel tetap berlaku.
CREATE FUNCTION public.printex_scoped_snapshot(p_start date, p_end date, p_order uuid DEFAULT NULL,
  p_changes jsonb DEFAULT NULL, p_history_after uuid DEFAULT NULL, p_history_only boolean DEFAULT false,
  p_history_ids text[] DEFAULT NULL)
RETURNS json LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE result json; period_start timestamptz; period_end timestamptz;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
  IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>365 THEN RAISE EXCEPTION 'Rentang data tidak valid'; END IF;
  period_start := p_start::timestamp AT TIME ZONE 'Asia/Jakarta';
  period_end := (p_end+1)::timestamp AT TIME ZONE 'Asia/Jakarta';
  WITH selected_identity AS MATERIALIZED (
    SELECT unnest(p_history_ids) AS identity WHERE p_history_ids IS NOT NULL
    UNION
    SELECT o.id::text FROM public.orders o WHERE p_history_ids IS NULL AND
      (o.archive_finalized_at IS NULL OR o.order_date BETWEEN p_start AND p_end
       OR o.archive_finalized_at>=period_start AND o.archive_finalized_at<period_end
       OR o.id=p_order)
    UNION
    SELECT h.order_identity FROM public.process_history h WHERE p_history_ids IS NULL
      AND h.occurred_at>=period_start AND h.occurred_at<period_end
  ), selected_orders AS MATERIALIZED (
    SELECT o.id,o.customer_id FROM public.orders o JOIN selected_identity i ON i.identity=o.id::text
  ), changed AS MATERIALIZED (
    SELECT item->>'table' AS table_name,item->>'id' AS id FROM jsonb_array_elements(coalesce(p_changes,'[]'::jsonb)) item
  ), history_page AS MATERIALIZED (
    SELECT h.id,h.order_identity,h.spk_code,h.step_id,h.event_kind,h.occurred_at,h.customer_name,h.next_step_id,h.next_event_id
    FROM public.process_history h JOIN selected_identity i ON i.identity=h.order_identity
    WHERE (p_history_after IS NULL OR h.id>p_history_after)
      AND h.step_id NOT IN (SELECT id FROM public.production_steps WHERE code='ARCHIVE')
      AND (p_changes IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name='process_history' AND c.id=h.id::text))
    ORDER BY h.id LIMIT 5001
  ), history_rows AS MATERIALIZED (SELECT * FROM history_page ORDER BY id LIMIT 5000)
  SELECT json_build_object(
    'orders',CASE WHEN p_history_only THEN '[]'::json ELSE coalesce((SELECT json_agg(row_to_json(o))
      FROM public.orders o JOIN selected_orders s ON s.id=o.id
      WHERE p_changes IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name='orders' AND c.id=o.id::text)),'[]'::json) END,
    'customers',CASE WHEN p_history_only THEN '[]'::json ELSE coalesce((SELECT json_agg(json_build_object('id',t.id,'name',t.name,'phone',t.phone))
      FROM public.customers t WHERE EXISTS(SELECT 1 FROM selected_orders o WHERE o.customer_id=t.id)
      AND (p_changes IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name='customers' AND c.id=t.id::text))),'[]'::json) END,
    'production_steps',CASE WHEN p_history_only THEN '[]'::json ELSE coalesce((SELECT json_agg(json_build_object('id',t.id,'code',t.code))
      FROM public.production_steps t
      WHERE p_changes IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name='production_steps' AND c.id=t.id::text)),'[]'::json) END,
    'process_history',coalesce((SELECT json_agg(json_build_object(
      'id',h.id,'order_identity',h.order_identity,'spk_code',h.spk_code,'step_id',h.step_id,
      'event_kind',h.event_kind,'occurred_at',h.occurred_at,'customer_name',h.customer_name,
      'next_step_id',h.next_step_id,'next_event_id',h.next_event_id)) FROM history_rows h),'[]'::json),
    'history_more',(SELECT count(*)>5000 FROM history_page),
    'history_cursor',(SELECT id FROM history_rows ORDER BY id DESC LIMIT 1),
    'identities',CASE WHEN p_history_only THEN '[]'::json ELSE coalesce((SELECT json_agg(identity) FROM selected_identity),'[]'::json) END
  ) INTO result;
  RETURN result;
END $$;

-- Realtime Supabase memberi tanda ada perubahan; datanya diambil lewat printex_sync_changes.
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['profiles','customers','production_steps','orders','process_history'] LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t);
    END IF;
  END LOOP;
END $$;

-- supabase/schema/05_foto_order.sql
-- Foto order opsional di bucket privat 'order-photos' (JPG/PNG/WebP, maks. 5 MB).
-- Owner/Admin mengunggah dan menautkan; semua karyawan aktif bisa melihat. File lama dihapus aman
-- lewat Storage API setelah diklaim di antrean pembersihan (tidak pernah menghapus metadata Storage).

INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
VALUES ('order-photos','order-photos',false,5242880,ARRAY['image/jpeg','image/png','image/webp'])
ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=5242880,
  allowed_mime_types=ARRAY['image/jpeg','image/png','image/webp'];

-- Antrean foto yang dilepas dari order; claimed=true berarti boleh dihapus dan tidak bisa ditautkan lagi.
CREATE TABLE public.order_photo_cleanup (
  path text PRIMARY KEY,
  claimed boolean NOT NULL DEFAULT false,
  queued_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.order_photo_cleanup ENABLE ROW LEVEL SECURITY;

-- Foto lama masuk antrean saat diganti, dilepas saat arsip final, atau order dihapus.
CREATE FUNCTION public.printex_queue_old_photo() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF OLD.photo_path IS NOT NULL AND (TG_OP='DELETE' OR OLD.photo_path IS DISTINCT FROM NEW.photo_path) THEN
    INSERT INTO public.order_photo_cleanup(path) VALUES(OLD.photo_path) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER orders_queue_old_photo AFTER DELETE OR UPDATE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.printex_queue_old_photo();

CREATE FUNCTION public.printex_set_order_photo(p_order_id uuid, p_expected_version bigint, p_path text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders;
BEGIN
  PERFORM 1 FROM public.profiles WHERE id=auth.uid() AND is_active AND role IN ('owner','admin') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Hanya Owner/Admin yang dapat mengubah foto order' USING ERRCODE='42501'; END IF;
  IF p_path IS NOT NULL THEN
    -- Kunci yang sama dipakai pembersihan: foto yang sudah diklaim tidak bisa ditautkan lagi.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_path,16));
    IF EXISTS(SELECT 1 FROM public.order_photo_cleanup WHERE path=p_path AND claimed) THEN
      RAISE EXCEPTION 'Foto sudah dijadwalkan untuk dibersihkan. Unggah ulang foto.';
    END IF;
  END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF;
  IF o.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Foto order arsip tidak dapat diubah'; END IF;
  IF o.photo_path IS NOT DISTINCT FROM p_path THEN RETURN; END IF;
  IF o.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'Order sudah diubah perangkat lain. Muat ulang dan coba lagi.' USING ERRCODE='40001';
  END IF;
  IF p_path IS NOT NULL THEN
    IF p_path !~ ('^'||p_order_id::text||'/[0-9a-f-]{36}\.(jpg|png|webp)$') THEN RAISE EXCEPTION 'Lokasi foto tidak valid'; END IF;
    PERFORM 1 FROM storage.objects WHERE bucket_id='order-photos' AND name=p_path FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Foto belum diunggah'; END IF;
  END IF;
  UPDATE public.orders SET photo_path=p_path WHERE id=p_order_id;
  DELETE FROM public.order_photo_cleanup WHERE path=p_path AND NOT claimed;
END $$;

-- Klaim foto yatim untuk dihapus oleh server: p_path tertentu (unggahan gagal) atau maks. 50 foto yang
-- ada di antrean atau berumur lebih dari 24 jam tanpa order.
CREATE FUNCTION public.printex_claim_photo_cleanup(p_path text DEFAULT NULL)
RETURNS TABLE(path text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE candidate text;
BEGIN
  IF NOT public.printex_admin() THEN RAISE EXCEPTION 'Hanya Owner/Admin dapat membersihkan foto' USING ERRCODE='42501'; END IF;
  -- File yang sudah terhapus tidak perlu baris antrean lagi.
  DELETE FROM public.order_photo_cleanup q WHERE q.queued_at<now()-interval '1 day'
    AND NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='order-photos' AND s.name=q.path);
  FOR candidate IN
    SELECT s.name FROM storage.objects s
    WHERE s.bucket_id='order-photos'
      AND (CASE WHEN p_path IS NOT NULL THEN s.name=p_path
        ELSE s.created_at<now()-interval '24 hours' OR EXISTS(SELECT 1 FROM public.order_photo_cleanup q WHERE q.path=s.name) END)
      AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=s.name)
    ORDER BY s.created_at,s.name LIMIT 50
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(candidate,16));
    IF NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=candidate) THEN
      -- Nama constraint, karena 'path' juga nama kolom hasil fungsi ini.
      INSERT INTO public.order_photo_cleanup AS q(path,claimed) VALUES(candidate,true)
        ON CONFLICT ON CONSTRAINT order_photo_cleanup_pkey DO UPDATE SET claimed=true;
      path := candidate; RETURN NEXT;
    END IF;
  END LOOP;
END $$;

CREATE FUNCTION public.printex_photo_deletable(p_path text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT public.printex_admin()
    AND EXISTS(SELECT 1 FROM public.order_photo_cleanup q WHERE q.path=p_path AND q.claimed)
    AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=p_path);
$$;

DROP POLICY IF EXISTS order_photos_read ON storage.objects;
CREATE POLICY order_photos_read ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id='order-photos' AND public.printex_staff());
-- Unggahan memakai path baru yang unik di folder order yang belum diarsipkan.
DROP POLICY IF EXISTS order_photos_upload ON storage.objects;
CREATE POLICY order_photos_upload ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id='order-photos' AND public.printex_admin()
    AND name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$'
    AND EXISTS(SELECT 1 FROM public.orders o WHERE o.id::text=split_part(name,'/',1) AND o.archived_at IS NULL));
DROP POLICY IF EXISTS order_photos_delete ON storage.objects;
CREATE POLICY order_photos_delete ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id='order-photos' AND public.printex_photo_deletable(name));

-- supabase/schema/06_laporan_harian.sql
-- Laporan harian tersimpan: kontribusi per order + total harian, diperbarui lewat antrean.
-- Hanya data turunan; order dan riwayat tidak pernah diubah dari sini.
-- Metrik: intake, intake_completed, output, paper, process, flow, timing, production, productivity, archive.

CREATE TABLE public.report_daily_summaries (
  report_date date NOT NULL,
  metric text NOT NULL,
  dimension text NOT NULL DEFAULT '',
  order_count bigint NOT NULL DEFAULT 0,
  meter numeric NOT NULL DEFAULT 0,
  milliseconds numeric NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (report_date,metric,dimension)
);
CREATE TABLE public.report_contributions (
  order_id uuid NOT NULL,
  report_date date NOT NULL,
  metric text NOT NULL,
  dimension text NOT NULL DEFAULT '',
  meter numeric NOT NULL DEFAULT 0,
  milliseconds numeric NOT NULL DEFAULT 0,
  data jsonb NOT NULL DEFAULT '{}',
  PRIMARY KEY (order_id,report_date,metric,dimension)
);
CREATE INDEX report_contributions_page ON public.report_contributions(metric,dimension,report_date DESC,order_id);
-- Data order disimpan sekali per order, bukan di setiap kontribusi.
CREATE TABLE public.report_order_payloads (
  order_id uuid PRIMARY KEY,
  data jsonb NOT NULL
);
CREATE TABLE public.report_refresh_queue (
  order_id uuid PRIMARY KEY,
  queued_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX report_refresh_queue_oldest ON public.report_refresh_queue(queued_at,order_id);
ALTER TABLE public.report_daily_summaries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.report_contributions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.report_order_payloads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.report_refresh_queue ENABLE ROW LEVEL SECURITY;

-- Total harian mengikuti setiap perubahan kontribusi.
CREATE FUNCTION public.printex_report_delta() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.report_contributions; sign integer;
BEGIN
  IF TG_OP='UPDATE' THEN
    UPDATE public.report_daily_summaries
      SET order_count=order_count-CASE WHEN OLD.metric='flow' THEN (OLD.data->>'visits')::bigint ELSE 1 END,
          meter=meter-OLD.meter,milliseconds=milliseconds-OLD.milliseconds
      WHERE report_date=OLD.report_date AND metric=OLD.metric AND dimension=OLD.dimension;
  END IF;
  IF TG_OP='DELETE' THEN r:=OLD; sign:=-1; ELSE r:=NEW; sign:=1; END IF;
  INSERT INTO public.report_daily_summaries(report_date,metric,dimension,order_count,meter,milliseconds)
  VALUES(r.report_date,r.metric,r.dimension,sign*CASE WHEN r.metric='flow' THEN (r.data->>'visits')::bigint ELSE 1 END,
    sign*r.meter,sign*r.milliseconds)
  ON CONFLICT(report_date,metric,dimension) DO UPDATE SET
    order_count=public.report_daily_summaries.order_count+excluded.order_count,
    meter=public.report_daily_summaries.meter+excluded.meter,
    milliseconds=public.report_daily_summaries.milliseconds+excluded.milliseconds,updated_at=now();
  RETURN NULL;
END $$;
CREATE TRIGGER report_contribution_delta AFTER INSERT OR UPDATE OR DELETE ON public.report_contributions
  FOR EACH ROW EXECUTE FUNCTION public.printex_report_delta();

CREATE FUNCTION public.printex_compact_report_payload() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NEW.data ? 'order' AND NEW.data->'order'<>'null'::jsonb THEN
    INSERT INTO public.report_order_payloads(order_id,data) VALUES(NEW.order_id,NEW.data->'order')
    ON CONFLICT(order_id) DO UPDATE SET data=excluded.data WHERE public.report_order_payloads.data IS DISTINCT FROM excluded.data;
    NEW.data := jsonb_set(NEW.data,'{order}','null'::jsonb);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER report_compact_payload BEFORE INSERT OR UPDATE ON public.report_contributions
  FOR EACH ROW EXECUTE FUNCTION public.printex_compact_report_payload();

CREATE VIEW public.printex_report_expanded AS
SELECT c.order_id,c.report_date,c.metric,c.dimension,c.meter,c.milliseconds,
  CASE WHEN c.data ? 'order' AND p.order_id IS NOT NULL THEN jsonb_set(c.data,'{order}',p.data) ELSE c.data END AS data
FROM public.report_contributions c LEFT JOIN public.report_order_payloads p ON p.order_id=c.order_id;

-- Order, riwayat, dan nama customer yang berubah masuk antrean.
CREATE FUNCTION public.printex_queue_report() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oid uuid; identity text;
BEGIN
  IF TG_TABLE_NAME='process_history' THEN
    identity := CASE WHEN TG_OP='DELETE' THEN OLD.order_identity ELSE NEW.order_identity END;
    oid := CASE WHEN identity ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN identity::uuid END;
  ELSE
    oid := CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
  END IF;
  IF oid IS NOT NULL THEN
    INSERT INTO public.report_refresh_queue(order_id) VALUES(oid) ON CONFLICT(order_id) DO UPDATE SET queued_at=now();
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER orders_queue_report AFTER INSERT OR UPDATE OR DELETE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.printex_queue_report();
CREATE TRIGGER history_queue_report AFTER INSERT OR UPDATE OR DELETE ON public.process_history
  FOR EACH ROW EXECUTE FUNCTION public.printex_queue_report();

CREATE FUNCTION public.printex_queue_customer_report() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NEW.name IS DISTINCT FROM OLD.name THEN
    INSERT INTO public.report_refresh_queue(order_id) SELECT id FROM public.orders WHERE customer_id=NEW.id
    ON CONFLICT(order_id) DO UPDATE SET queued_at=now();
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER customers_queue_report AFTER UPDATE ON public.customers
  FOR EACH ROW EXECUTE FUNCTION public.printex_queue_customer_report();

CREATE FUNCTION public.printex_report_add(p_id uuid, p_day date, p_metric text, p_dimension text DEFAULT '',
  p_meter numeric DEFAULT 0, p_ms numeric DEFAULT 0, p_data jsonb DEFAULT '{}')
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
  INSERT INTO public.report_contributions(order_id,report_date,metric,dimension,meter,milliseconds,data)
  VALUES(p_id,p_day,p_metric,p_dimension,p_meter,p_ms,p_data)
  ON CONFLICT DO NOTHING;
$$;

-- Hitung ulang seluruh kontribusi satu order dari order dan riwayatnya (zona waktu Asia/Jakarta).
CREATE FUNCTION public.printex_refresh_report_order(p_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; customer text; events jsonb; e jsonb; code text; kind text;
  stamp timestamptz; started timestamptz; completed timestamptz; last_stamp timestamptz; ending timestamptz;
  open_code text; open_at timestamptz; flow_code text; flow_at timestamptz;
  durations jsonb:='{}'; exits jsonb:='{}'; visited jsonb:='{}'; ms numeric; day date; dim text;
  payload jsonb; order_data jsonb; base jsonb; is_finished boolean; timing_code text;
BEGIN
  SELECT * INTO o FROM public.orders WHERE id=p_id;
  DELETE FROM public.report_contributions WHERE order_id=p_id;
  DELETE FROM public.report_order_payloads WHERE order_id=p_id;
  -- Order yang dihapus tetap punya milestone proses selama riwayatnya ada.
  IF o.id IS NULL AND NOT EXISTS(SELECT 1 FROM public.process_history WHERE order_identity=p_id::text) THEN RETURN; END IF;
  SELECT name INTO customer FROM public.customers WHERE id=o.customer_id;
  order_data := jsonb_build_object('id',o.id,'spk_code',o.spk_code,'customer',jsonb_build_object('name',coalesce(customer,''),'phone',''),
    'production_type',o.production_type,'meter',coalesce(o.meter,0),'paper_width',o.paper_width,'customer_type',o.customer_type,
    'order_date',o.order_date,'due_at',o.due_at,'order_state',o.order_state,'photo_path',o.photo_path,
    'archive',CASE WHEN o.archived_at IS NULL THEN NULL ELSE jsonb_build_object('archivedAt',o.archived_at,
      'finalizedAt',o.archive_finalized_at,'deliveryMethod',o.delivery_method) END);
  -- Riwayat ringkas dibuka menjadi kejadian (tahap ditinggalkan + tahap tujuan).
  SELECT coalesce(jsonb_agg(t.data ORDER BY t.stamp,(t.kind='entered')::integer,t.id),'[]') INTO events FROM (
    SELECT h.id,h.occurred_at AS stamp,h.event_kind AS kind,
      jsonb_build_object('id',h.id,'code',s.code,'kind',h.event_kind,'at',h.occurred_at,'customer',h.customer_name,'spk',h.spk_code) AS data
    FROM public.process_history h JOIN public.production_steps s ON s.id=h.step_id WHERE h.order_identity=p_id::text
    UNION ALL
    SELECT h.next_event_id,h.occurred_at,'entered',
      jsonb_build_object('id',h.next_event_id,'code',s.code,'kind','entered','at',h.occurred_at,'customer',h.customer_name,'spk',h.spk_code)
    FROM public.process_history h JOIN public.production_steps s ON s.id=h.next_step_id WHERE h.order_identity=p_id::text
  ) t;
  -- Milestone selesai pertama per tahap (proses, output cetak, kertas).
  FOR e IN SELECT DISTINCT ON (value->>'code') value FROM jsonb_array_elements(events)
    WHERE value->>'kind'='completed' AND value->>'code' NOT IN ('DONE','ARCHIVE')
    ORDER BY value->>'code',(value->>'at')::timestamptz,value->>'id' LOOP
    code := e->>'code'; stamp := (e->>'at')::timestamptz; day := (stamp AT TIME ZONE 'Asia/Jakarta')::date;
    base := jsonb_build_object('id',e->>'id','orderId',p_id,'spkCode',e->>'spk','customerName',coalesce(e->>'customer',''),
      'kind','completed','orderExists',o.id IS NOT NULL,'occurredAt',stamp,'actorName',NULL);
    PERFORM public.printex_report_add(p_id,day,'process',code,0,0,jsonb_build_object('event',base));
    IF code='PRINTING' AND o.id IS NOT NULL THEN
      dim := CASE WHEN upper(trim(o.production_type))='DTF' THEN 'dtf' ELSE 'sublim' END;
      PERFORM public.printex_report_add(p_id,day,'output',dim,greatest(o.meter,0));
      dim := CASE WHEN upper(trim(o.production_type))='DTF' THEN '0.6'
        WHEN o.paper_width IN (1.2,1.6,1.8) THEN trim(trailing '0' FROM o.paper_width::text) ELSE 'unknown' END;
      dim := CASE WHEN dim IN ('1.2','1.6','1.8','0.6') THEN dim ELSE 'unknown' END;
      PERFORM public.printex_report_add(p_id,day,'paper',dim,greatest(o.meter,0));
    END IF;
  END LOOP;
  IF o.id IS NULL THEN RETURN; END IF;
  PERFORM public.printex_report_add(p_id,o.order_date,'intake','');
  IF o.order_state='completed' OR o.archive_finalized_at IS NOT NULL THEN
    PERFORM public.printex_report_add(p_id,o.order_date,'intake_completed','');
  END IF;
  IF o.archive_finalized_at IS NOT NULL THEN
    day := (o.archive_finalized_at AT TIME ZONE 'Asia/Jakarta')::date;
    PERFORM public.printex_report_add(p_id,day,'archive','',greatest(o.meter,0),0,jsonb_build_object('order',order_data));
    base := jsonb_build_object('id','archive-completed-'||p_id,'orderId',p_id,'spkCode',o.spk_code,'customerName',coalesce(customer,''),
      'kind','completed','orderExists',true,'occurredAt',o.archive_finalized_at,'actorName',NULL);
    PERFORM public.printex_report_add(p_id,day,'process','DONE',0,0,jsonb_build_object('event',base));
  END IF;
  SELECT min((value->>'at')::timestamptz) FILTER(WHERE value->>'kind'='entered' AND value->>'code' IN ('DESIGN','DESIGN_DONE')),
    min((value->>'at')::timestamptz) FILTER(WHERE value->>'kind'='entered' AND value->>'code'='DONE'),
    max((value->>'at')::timestamptz)
  INTO started,completed,last_stamp FROM jsonb_array_elements(events);
  is_finished := completed IS NOT NULL OR (SELECT s.code IN ('DONE','ARCHIVE') FROM public.production_steps s WHERE s.id=o.current_step_id);
  ending := coalesce(completed,last_stamp);
  FOR e IN SELECT value FROM jsonb_array_elements(events) LOOP
    code := e->>'code'; kind := e->>'kind'; stamp := (e->>'at')::timestamptz;
    -- Rata-rata alur menghitung semua kunjungan nyata; kembali ke tahap sebelumnya bukan penyelesaian.
    IF flow_code IS NOT NULL AND (kind='entered' OR flow_code=code) AND NOT(kind='entered' AND flow_code=code) THEN
      IF kind='completed' OR (kind='entered'
         AND (SELECT s.sequence FROM public.production_steps s WHERE s.code=e->>'code')>(SELECT s.sequence FROM public.production_steps s WHERE s.code=flow_code)) THEN
        day := (stamp AT TIME ZONE 'Asia/Jakarta')::date;
        INSERT INTO public.report_contributions(order_id,report_date,metric,dimension,milliseconds,data)
        VALUES(p_id,day,'flow',flow_code,greatest(extract(epoch FROM stamp-flow_at)*1000,0),jsonb_build_object('visits',1))
        ON CONFLICT(order_id,report_date,metric,dimension) DO UPDATE SET
          milliseconds=public.report_contributions.milliseconds+excluded.milliseconds,
          data=jsonb_build_object('visits',(public.report_contributions.data->>'visits')::integer+1);
      END IF;
      flow_code := NULL;
    END IF;
    IF kind='entered' AND flow_code IS DISTINCT FROM code THEN flow_code := code; flow_at := stamp; END IF;
    IF started IS NULL OR stamp<started OR stamp>ending THEN CONTINUE; END IF;
    IF (kind<>'entered' AND open_code=code) OR (kind='entered' AND open_code IS NOT NULL AND open_code IS DISTINCT FROM code) THEN
      ms := greatest(extract(epoch FROM least(stamp,ending)-open_at)*1000,0);
      durations := jsonb_set(durations,ARRAY[open_code],to_jsonb(coalesce((durations->>open_code)::numeric,0)+ms));
      exits := jsonb_set(exits,ARRAY[open_code],to_jsonb(least(stamp,ending))); open_code := NULL;
    END IF;
    IF kind='entered' AND code IN ('DESIGN','DESIGN_DONE','PRINTING','PRESS') AND open_code IS DISTINCT FROM code THEN
      open_code := code; open_at := stamp; visited := jsonb_set(visited,ARRAY[code],'true');
    END IF;
  END LOOP;
  IF open_code IS NOT NULL AND is_finished THEN
    durations := jsonb_set(durations,ARRAY[open_code],
      to_jsonb(coalesce((durations->>open_code)::numeric,0)+greatest(extract(epoch FROM ending-open_at)*1000,0)));
    IF completed IS NOT NULL THEN exits := jsonb_set(exits,ARRAY[open_code],to_jsonb(completed)); END IF;
  END IF;
  payload := jsonb_build_object('order',order_data,'productionMilliseconds',
    CASE WHEN started IS NOT NULL AND completed IS NOT NULL THEN greatest(extract(epoch FROM completed-started)*1000,0) END);
  IF started IS NOT NULL AND completed IS NOT NULL THEN
    day := (completed AT TIME ZONE 'Asia/Jakarta')::date;
    PERFORM public.printex_report_add(p_id,day,'production','',0,greatest(extract(epoch FROM completed-started)*1000,0),payload);
  END IF;
  -- Waktu per tahap dan produktivitas cetak/press (meter per jam per jenis kertas).
  FOREACH timing_code IN ARRAY ARRAY['DESIGN','DESIGN_DONE','PRINTING','PRESS'] LOOP
    IF visited ? timing_code AND exits ? timing_code AND NOT(coalesce(NOT is_finished AND open_code=timing_code,false)) THEN
      day := ((exits->>timing_code)::timestamptz AT TIME ZONE 'Asia/Jakarta')::date;
      ms := coalesce((durations->>timing_code)::numeric,0);
      PERFORM public.printex_report_add(p_id,day,'timing',timing_code,0,ms,payload);
      IF timing_code IN ('PRINTING','PRESS') THEN
        dim := CASE WHEN timing_code='PRESS' THEN 'press' WHEN upper(trim(o.production_type))='DTF' THEN 'dtf' ELSE 'sublim' END;
        PERFORM public.printex_report_add(p_id,day,'productivity',
          dim||':'||CASE WHEN upper(trim(o.production_type))='DTF' THEN 'dtf' ELSE coalesce((o.paper_width::float8)::text,'unknown') END,
          greatest(o.meter,0),ms);
      END IF;
    END IF;
  END LOOP;
END $$;

-- Pekerja latar (pg_cron tiap menit): proses maks. 500 order dari antrean.
CREATE FUNCTION public.printex_refresh_report_queue(p_limit integer DEFAULT 100) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r record; refreshed integer:=0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(73621,1) THEN RETURN -1; END IF;
  FOR r IN SELECT order_id FROM public.report_refresh_queue ORDER BY queued_at,order_id
    LIMIT least(greatest(p_limit,1),500) FOR UPDATE SKIP LOCKED LOOP
    PERFORM public.printex_refresh_report_order(r.order_id);
    DELETE FROM public.report_refresh_queue WHERE order_id=r.order_id;
    refreshed := refreshed+1;
  END LOOP;
  RETURN refreshed;
END $$;

-- Total harian untuk halaman Laporan; ikut memproses 100 antrean agar data terbaru langsung terlihat.
CREATE FUNCTION public.printex_daily_report(p_start date, p_end date) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r record; pending boolean; result jsonb;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
  IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>365 THEN RAISE EXCEPTION 'Rentang laporan tidak valid'; END IF;
  IF pg_try_advisory_xact_lock(73621,1) THEN
    FOR r IN SELECT order_id FROM public.report_refresh_queue ORDER BY queued_at,order_id LIMIT 100 FOR UPDATE SKIP LOCKED LOOP
      PERFORM public.printex_refresh_report_order(r.order_id);
      DELETE FROM public.report_refresh_queue WHERE order_id=r.order_id;
    END LOOP;
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.report_refresh_queue) INTO pending;
  SELECT coalesce(jsonb_agg(jsonb_build_object('day',report_date,'metric',metric,'dimension',dimension,'count',order_count,
    'meter',meter,'milliseconds',milliseconds) ORDER BY report_date,metric,dimension),'[]') INTO result
  FROM public.report_daily_summaries WHERE report_date BETWEEN p_start AND p_end AND order_count>0;
  RETURN jsonb_build_object('rows',result,'pending',pending,'asOf',now());
END $$;

-- Rincian satu metrik/dimensi (arsip, proses, waktu tahap, produksi), dengan pencarian SPK/customer.
CREATE FUNCTION public.printex_report_details(p_start date, p_end date, p_metric text, p_dimension text DEFAULT '',
  p_offset integer DEFAULT 0, p_limit integer DEFAULT 50, p_search text DEFAULT '')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb; total bigint;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
  IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>365 OR p_metric IS NULL
     OR p_metric NOT IN ('archive','process','timing','production') OR p_offset IS NULL OR p_offset<0 THEN
    RAISE EXCEPTION 'Filter laporan tidak valid';
  END IF;
  SELECT count(*) INTO total FROM public.printex_report_expanded
  WHERE report_date BETWEEN p_start AND p_end AND metric=p_metric AND dimension=p_dimension
    AND (p_search='' OR position(lower(p_search) IN lower(coalesce(data->'order'->>'spk_code',data->'event'->>'spkCode','')
      ||' '||coalesce(data->'order'->'customer'->>'name',data->'event'->>'customerName','')))>0);
  SELECT coalesce(jsonb_agg(t.data),'[]') INTO result FROM (
    SELECT data||jsonb_build_object('milliseconds',milliseconds,'day',report_date) AS data FROM public.printex_report_expanded
    WHERE report_date BETWEEN p_start AND p_end AND metric=p_metric AND dimension=p_dimension
      AND (p_search='' OR position(lower(p_search) IN lower(coalesce(data->'order'->>'spk_code',data->'event'->>'spkCode','')
        ||' '||coalesce(data->'order'->'customer'->>'name',data->'event'->>'customerName','')))>0)
    ORDER BY report_date DESC,order_id LIMIT least(greatest(p_limit,1),200) OFFSET p_offset) t;
  RETURN jsonb_build_object('items',result,'total',total);
END $$;

-- Antrean diproses tiap menit bila pg_cron tersedia (menjadwalkan ulang dengan nama sama aman).
DO $$ BEGIN
  IF to_regnamespace('cron') IS NOT NULL THEN
    EXECUTE 'SELECT cron.schedule(''printex-daily-report-refresh'',''* * * * *'',''SELECT public.printex_refresh_report_queue(500);'')';
  END IF;
END $$;

-- supabase/schema/07_kapasitas_produksi.sql
-- Kapasitas produksi: catatan Mulai/Selesai mesin, jam operator per hari, dan data efisiensi.
-- Press DTF memakai lini sendiri di luar dashboard: tidak dicatat dan tidak dihitung di stasiun Press.

-- Hari yang berbeda dari operator standar (orang x jam per orang). 0 orang boleh.
CREATE TABLE public.operator_shifts (
  work_date date NOT NULL,
  stage text NOT NULL CHECK (stage IN ('design','printing','press','dtf')),
  people smallint NOT NULL CHECK (people BETWEEN 0 AND 50),
  hours numeric(4,2) NOT NULL CHECK (hours > 0 AND hours <= 24),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (work_date,stage)
);

-- Catatan "Mulai/Selesai cetak": satu catatan terbuka per order dan per mesin.
CREATE TABLE public.print_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  machine_id uuid REFERENCES public.production_machines(id) ON DELETE SET NULL,
  stage text NOT NULL CHECK (stage IN ('printing','press')),
  started_at timestamptz NOT NULL DEFAULT now(),
  ended_at timestamptz CHECK (ended_at >= started_at)
);
CREATE UNIQUE INDEX print_runs_open_order ON public.print_runs(order_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX print_runs_open_machine ON public.print_runs(machine_id) WHERE ended_at IS NULL AND machine_id IS NOT NULL;
CREATE INDEX print_runs_period ON public.print_runs(started_at);

ALTER TABLE public.operator_shifts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.print_runs ENABLE ROW LEVEL SECURITY;
-- Penulisan hanya lewat fungsi di bawah.
CREATE POLICY operator_shifts_read ON public.operator_shifts FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY print_runs_read ON public.print_runs FOR SELECT TO authenticated USING (public.printex_staff());

-- Order yang pindah tahap otomatis menutup catatan yang masih berjalan.
CREATE FUNCTION public.printex_close_runs_on_move() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  UPDATE public.print_runs SET ended_at=greatest(started_at,now()) WHERE order_id=NEW.id AND ended_at IS NULL;
  RETURN NEW;
END $$;
CREATE TRIGGER close_runs_on_move AFTER UPDATE OF current_step_id ON public.orders
  FOR EACH ROW WHEN (OLD.current_step_id IS DISTINCT FROM NEW.current_step_id)
  EXECUTE FUNCTION public.printex_close_runs_on_move();

-- Admin mengisi jam operator suatu hari; p_people NULL mengembalikan hari itu ke operator standar.
CREATE FUNCTION public.printex_set_operator_shift(p_date date, p_stage text, p_people integer, p_hours numeric)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NOT public.printex_admin() THEN RAISE EXCEPTION 'Hanya admin yang dapat mengisi jam operator' USING ERRCODE='42501'; END IF;
  IF p_date IS NULL OR p_date>(now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Tanggal tidak valid'; END IF;
  IF p_people IS NULL THEN
    DELETE FROM public.operator_shifts WHERE work_date=p_date AND stage=p_stage;
    RETURN;
  END IF;
  INSERT INTO public.operator_shifts(work_date,stage,people,hours) VALUES(p_date,p_stage,p_people,p_hours)
  ON CONFLICT(work_date,stage) DO UPDATE SET people=excluded.people,hours=excluded.hours,updated_at=now();
END $$;

-- Mulai cetak/press. Cetak memakai mesin order; press memakai satu-satunya mesin Press bila hanya ada satu.
CREATE FUNCTION public.printex_start_run(p_order uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; step text; run_stage text; machine uuid; busy text; new_id uuid;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF;
  SELECT code INTO step FROM public.production_steps WHERE id=o.current_step_id;
  run_stage := CASE step WHEN 'PRINTING' THEN 'printing' WHEN 'PRESS' THEN 'press' END;
  IF run_stage IS NULL THEN RAISE EXCEPTION 'Mulai cetak hanya untuk order di Proses Sublim atau Proses Press'; END IF;
  IF run_stage='press' AND upper(btrim(o.production_type))='DTF' THEN RAISE EXCEPTION 'Press DTF memakai lini sendiri dan tidak dicatat'; END IF;
  IF EXISTS(SELECT 1 FROM public.print_runs WHERE order_id=p_order AND ended_at IS NULL) THEN RAISE EXCEPTION 'Order ini sedang berjalan'; END IF;
  IF run_stage='printing' THEN
    machine := o.print_machine_id;
    IF machine IS NULL THEN RAISE EXCEPTION 'Pilih mesin print terlebih dahulu'; END IF;
  ELSE
    SELECT CASE WHEN count(*)=1 THEN (array_agg(id))[1] END INTO machine
    FROM public.production_machines WHERE kind='press' AND removed_at IS NULL;
  END IF;
  IF machine IS NOT NULL THEN
    SELECT x.spk_code INTO busy FROM public.print_runs r JOIN public.orders x ON x.id=r.order_id
    WHERE r.machine_id=machine AND r.ended_at IS NULL;
    IF busy IS NOT NULL THEN RAISE EXCEPTION 'Mesin masih mengerjakan SPK %. Selesaikan dulu.', busy; END IF;
  END IF;
  INSERT INTO public.print_runs(order_id,machine_id,stage) VALUES(p_order,machine,run_stage) RETURNING id INTO new_id;
  RETURN new_id;
END $$;

CREATE FUNCTION public.printex_finish_run(p_order uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  UPDATE public.print_runs SET ended_at=now() WHERE order_id=p_order AND ended_at IS NULL;
END $$;

-- Data kapasitas K = P x T untuk satu periode:
--   runs   = waktu mesin berjalan, meter, dan jumlah order selesai per mesin dan stasiun (tanpa press DTF);
--   shifts = jam-orang per stasiun di hari kerja (hari dengan aktivitas produksi atau isian jam operator):
--            isian hari itu, selain itu operator standar x jam efektif.
CREATE FUNCTION public.printex_efficiency_inputs(p_start date, p_end date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE ps timestamptz; pe timestamptz;
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>366 THEN RAISE EXCEPTION 'Periode tidak valid'; END IF;
  ps := p_start::timestamp AT TIME ZONE 'Asia/Jakarta';
  pe := least((p_end+1)::timestamp AT TIME ZONE 'Asia/Jakarta',now());
  RETURN jsonb_build_object(
    'runs',coalesce((SELECT jsonb_agg(jsonb_build_object('machineId',x.machine_id,'stage',x.stage,'milliseconds',x.ms,'meter',x.meter,'count',x.n)) FROM (
      SELECT r.machine_id,r.stage,
        sum(greatest(0,extract(epoch FROM least(coalesce(r.ended_at,now()),pe)-greatest(r.started_at,ps)))*1000)::bigint AS ms,
        sum(CASE WHEN r.ended_at>=ps AND r.ended_at<pe THEN o.meter ELSE 0 END) AS meter,
        count(*) FILTER (WHERE r.ended_at>=ps AND r.ended_at<pe) AS n
      FROM public.print_runs r JOIN public.orders o ON o.id=r.order_id
      WHERE r.started_at<pe AND coalesce(r.ended_at,now())>ps
        AND NOT (r.stage='press' AND upper(btrim(o.production_type))='DTF')
      GROUP BY r.machine_id,r.stage) x),'[]'::jsonb),
    'shifts',coalesce((SELECT jsonb_agg(jsonb_build_object('stage',x.stage,'manHours',x.mh,'peopleDays',x.pd)) FROM (
      WITH days AS (
        SELECT DISTINCT (h.occurred_at AT TIME ZONE 'Asia/Jakarta')::date AS d FROM public.process_history h
        WHERE h.occurred_at>=ps AND h.occurred_at<pe
        UNION
        SELECT s.work_date FROM public.operator_shifts s WHERE s.work_date BETWEEN p_start AND p_end
      ), crew AS (
        SELECT st.stage,
          coalesce(s.people,CASE st.stage WHEN 'printing' THEN c.operators_printing WHEN 'dtf' THEN c.operators_dtf
            WHEN 'press' THEN c.operators_press ELSE c.operators_design END) AS people,
          coalesce(s.hours,c.effective_hours) AS hours
        FROM days dy CROSS JOIN public.production_settings c
        CROSS JOIN (VALUES ('design'),('printing'),('press'),('dtf')) st(stage)
        LEFT JOIN public.operator_shifts s ON s.work_date=dy.d AND s.stage=st.stage
      )
      SELECT stage,sum(people*hours) AS mh,sum(people) AS pd FROM crew WHERE people>0 GROUP BY stage) x),'[]'::jsonb)
  );
END $$;

-- Produktivitas cetak per mesin dari laporan tersimpan (waktu tahap per order).
CREATE FUNCTION public.printex_machine_productivity(p_start date, p_end date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>366 THEN RAISE EXCEPTION 'Periode tidak valid'; END IF;
  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('machineId',x.machine,'dimension',x.dimension,'count',x.n,'meter',x.meter,'milliseconds',x.ms))
    FROM (SELECT o.print_machine_id AS machine,c.dimension,count(*) AS n,sum(c.meter) AS meter,sum(c.milliseconds) AS ms
      FROM public.report_contributions c JOIN public.orders o ON o.id=c.order_id
      WHERE c.metric='productivity' AND (c.dimension LIKE 'sublim:%' OR c.dimension LIKE 'dtf:%')
        AND c.report_date BETWEEN p_start AND p_end AND o.print_machine_id IS NOT NULL
      GROUP BY o.print_machine_id,c.dimension) x),'[]'::jsonb);
END $$;

-- supabase/schema/08_pengaturan_bersama.sql
-- Pengaturan bersama yang diubah Owner/Admin: tombol link stok di Board Produksi dan nomor Customer Service.

-- Link kosong = tombol nonaktif. version dipakai untuk penguncian optimistis dari aplikasi.
CREATE TABLE public.stock_shortcuts (
  id text PRIMARY KEY CHECK (id IN ('dtf_paper','fabric')),
  label text NOT NULL CHECK (length(trim(label)) BETWEEN 1 AND 60),
  url text NOT NULL CHECK (url='' OR (length(url)<=2048 AND url ~ '^https://[^[:space:]]+$')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0)
);
INSERT INTO public.stock_shortcuts(id,label,url) VALUES
  ('dtf_paper','Stock DTF dan Kertas','https://docs.google.com/spreadsheets/d/1qSXiNUIUOmJ_yPmtpB8CLEEk2OZCHMRkhH7m6b1NPM8/edit?gid=143541986#gid=143541986'),
  ('fabric','Stock Kain','https://docs.google.com/spreadsheets/d/1Ipag7VfEh8yyEBjhU52dL0TlE9bfh4lhcwow8CZ_HJA/edit?gid=255000558#gid=255000558');
ALTER TABLE public.stock_shortcuts ENABLE ROW LEVEL SECURITY;
CREATE POLICY stock_shortcuts_read ON public.stock_shortcuts FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY stock_shortcuts_edit ON public.stock_shortcuts FOR UPDATE TO authenticated
  USING (public.printex_admin()) WITH CHECK (public.printex_admin());

-- Nomor WhatsApp Customer Service (format internasional tanpa +, atau kosong).
CREATE TABLE public.customer_service_settings (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  whatsapp_number text NOT NULL DEFAULT '' CHECK (whatsapp_number='' OR whatsapp_number ~ '^[1-9][0-9]{7,14}$')
);
INSERT INTO public.customer_service_settings(singleton) VALUES (true);
ALTER TABLE public.customer_service_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_service_read ON public.customer_service_settings FOR SELECT TO authenticated USING (public.printex_staff());
CREATE POLICY customer_service_update ON public.customer_service_settings FOR UPDATE TO authenticated
  USING (public.printex_admin()) WITH CHECK (public.printex_admin());

-- supabase/schema/09_pembersihan_foto_terjadwal.sql
-- Pembersihan foto terjadwal (tiap 5 menit, diaktifkan dengan supabase/jobs/enable-photo-cleanup.sql).
-- Memakai pg_net dan Vault; keduanya baru dibutuhkan saat fungsi berjalan. Kredensial disimpan di Vault,
-- tidak pernah di file ini.

-- Permintaan hapus yang sudah dikirim; dikirim ulang setelah 4 menit bila file masih ada.
CREATE TABLE public.photo_cleanup_requests (
  path text PRIMARY KEY,
  request_id bigint NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.photo_cleanup_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.photo_cleanup_requests FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.printex_run_photo_cleanup() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE candidate text; endpoint text; api_key text; encoded text; request bigint; total integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('printex-scheduled-photo-cleanup',16)) THEN RETURN 0; END IF;
  SELECT decrypted_secret INTO endpoint FROM vault.decrypted_secrets WHERE name='printex_storage_url';
  SELECT decrypted_secret INTO api_key FROM vault.decrypted_secrets WHERE name='printex_storage_cleanup_key';
  IF endpoint IS NULL OR api_key IS NULL THEN RAISE EXCEPTION 'Photo cleanup credentials are not configured'; END IF;
  IF endpoint !~ '^https://[a-z0-9]+\.supabase\.co$' THEN RAISE EXCEPTION 'Invalid Storage endpoint'; END IF;

  DELETE FROM public.order_photo_cleanup q WHERE q.queued_at<now()-interval '1 day'
    AND NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='order-photos' AND s.name=q.path);
  DELETE FROM public.photo_cleanup_requests r WHERE r.requested_at<now()-interval '7 days'
    AND NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='order-photos' AND s.name=r.path);

  FOR candidate IN
    SELECT s.name FROM storage.objects s
    LEFT JOIN public.photo_cleanup_requests r ON r.path=s.name
    WHERE s.bucket_id='order-photos'
      AND (s.created_at<now()-interval '24 hours' OR EXISTS(SELECT 1 FROM public.order_photo_cleanup q WHERE q.path=s.name))
      AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=s.name)
      AND (r.requested_at IS NULL OR r.requested_at<now()-interval '4 minutes')
    ORDER BY r.requested_at NULLS FIRST,s.created_at,s.name LIMIT 50
  LOOP
    -- Kunci dan klaim yang sama dengan penautan foto.
    PERFORM pg_advisory_xact_lock(hashtextextended(candidate,16));
    IF NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=candidate) THEN
      INSERT INTO public.order_photo_cleanup AS q(path,claimed) VALUES(candidate,true)
      ON CONFLICT(path) DO UPDATE SET claimed=true;
      -- Encode UTF-8 per byte, pemisah folder dipertahankan.
      SELECT string_agg(CASE WHEN chr(b) ~ '^[A-Za-z0-9_~/.-]$' THEN chr(b) ELSE '%'||upper(lpad(to_hex(b),2,'0')) END,'' ORDER BY n)
      INTO encoded FROM (SELECT n,get_byte(convert_to(candidate,'UTF8'),n) AS b
        FROM generate_series(0,octet_length(convert_to(candidate,'UTF8'))-1) n) bytes;
      request := net.http_delete(
        url := endpoint||'/storage/v1/object/order-photos/'||encoded,
        headers := jsonb_build_object('apikey',api_key), timeout_milliseconds := 10000);
      INSERT INTO public.photo_cleanup_requests(path,request_id) VALUES(candidate,request)
      ON CONFLICT(path) DO UPDATE SET request_id=excluded.request_id,requested_at=now();
      total := total+1;
    END IF;
  END LOOP;
  -- pg_net mengirim setelah commit, jadi klaim tetap ada walau respons HTTP hilang.
  -- Penghapusan yang gagal dicoba lagi pada jadwal berikutnya; metadata Storage tidak pernah dihapus langsung.
  RETURN total;
END $$;
REVOKE ALL ON FUNCTION public.printex_run_photo_cleanup() FROM PUBLIC,anon,authenticated;

-- supabase/schema/10_hak_akses.sql
-- Status database untuk aplikasi dan seluruh hak akses di satu tempat.
-- Prinsip: anon tidak mendapat apa pun; karyawan (authenticated) hanya membaca tabel yang dibutuhkan,
-- mengubah beberapa kolom pengaturan lewat RLS, dan menulis data lain hanya lewat fungsi RPC.

-- Aplikasi menolak bekerja bila schema_version berbeda dari ACCESS_SCHEMA_VERSION (src/lib/access-control.ts).
CREATE FUNCTION public.printex_online_status() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif. Hubungi admin.' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('schema_version',9,'daily_summaries_enabled',true,'production_capacity_enabled',true,
    'realtime_tables',(SELECT jsonb_agg(tablename) FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public'));
END $$;

-- Mulai dari nol (Supabase memberi hak penuh bawaan pada objek baru di skema public).
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC, anon, authenticated;

-- Baca: dibatasi lagi oleh RLS (karyawan aktif; profil hanya milik sendiri kecuali Owner/Admin).
GRANT SELECT ON public.profiles, public.production_steps, public.production_machines, public.production_settings,
  public.customers, public.orders, public.process_history, public.operator_shifts, public.print_runs,
  public.stock_shortcuts, public.customer_service_settings TO authenticated;

-- Ubah langsung (hanya Owner/Admin lewat RLS, hanya kolom ini).
GRANT INSERT (kind,name), UPDATE (name,removed_at) ON public.production_machines TO authenticated;
GRANT UPDATE (shifts,shift_hours,planned_downtime_minutes,operators_printing,operators_dtf,operators_press,
  operators_design,design_orders_per_hour,version) ON public.production_settings TO authenticated;
GRANT UPDATE (label,url,version) ON public.stock_shortcuts TO authenticated;
GRANT UPDATE (whatsapp_number) ON public.customer_service_settings TO authenticated;

-- RPC aplikasi. Setiap fungsi memeriksa sendiri peran pemanggil.
GRANT EXECUTE ON FUNCTION
  public.printex_staff(), public.printex_admin(), public.printex_online_status(),
  public.printex_list_users(), public.printex_manage_user(uuid,text,text,boolean,boolean),
  public.printex_mutate_order(text,uuid,bigint,jsonb), public.printex_set_print_machine(uuid,bigint,uuid,boolean),
  public.printex_scoped_snapshot(date,date,uuid,jsonb,uuid,boolean,text[]), public.printex_sync_changes(bigint),
  public.printex_set_order_photo(uuid,bigint,text), public.printex_claim_photo_cleanup(text), public.printex_photo_deletable(text),
  public.printex_daily_report(date,date), public.printex_report_details(date,date,text,text,integer,integer,text),
  public.printex_set_operator_shift(date,text,integer,numeric), public.printex_start_run(uuid), public.printex_finish_run(uuid),
  public.printex_efficiency_inputs(date,date), public.printex_machine_productivity(date,date)
TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ===== Bagian 3: pulihkan akun & pengaturan, lalu hapus cadangan =====
DO $$
DECLARE s record;
BEGIN
 -- Akun: login dan password tetap; profil dibuat lagi dengan role dan status sebelumnya.
 INSERT INTO public.profiles(id,full_name,role,is_active)
  SELECT k.id,k.full_name,k.role,k.is_active FROM printex_keep.profiles k JOIN auth.users u ON u.id=k.id
 ON CONFLICT (id) DO UPDATE SET full_name=excluded.full_name,role=excluded.role,is_active=excluded.is_active,updated_at=now();
 IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE role='owner' AND is_active) THEN
  RAISE NOTICE 'Belum ada akun Owner. Buat akun di Authentication → Users, lalu jalankan supabase/ACTIVATE_ADMIN.sql.';
 END IF;

 -- Waktu kerja dan operator standar (tanpa cadangan: standar 9 jam, istirahat & setup 2 jam).
 SELECT * INTO s FROM printex_keep.settings LIMIT 1;
 IF FOUND THEN
  UPDATE public.production_settings SET shifts=s.shifts,shift_hours=s.shift_hours,planned_downtime_minutes=s.planned_downtime_minutes,
   operators_printing=s.operators_printing,operators_dtf=s.operators_dtf,operators_press=s.operators_press,operators_design=s.operators_design,
   design_orders_per_hour=s.design_orders_per_hour,version=version+1;
 END IF;

 -- Mesin tersimpan menggantikan mesin bawaan (belum ada order yang memakainya).
 IF EXISTS (SELECT 1 FROM printex_keep.machines) THEN
  DELETE FROM public.production_machines;
  INSERT INTO public.production_machines(kind,name,created_at) SELECT kind,name,created_at FROM printex_keep.machines;
 END IF;

 -- Link stok (link kosong = tombol nonaktif) dan nomor Customer Service.
 UPDATE public.stock_shortcuts t SET label=k.label,url=k.url,version=t.version+1
  FROM printex_keep.stock_shortcuts k WHERE k.id=t.id AND (k.url='' OR k.url ~ '^https://[^[:space:]]+$');
 UPDATE public.customer_service_settings SET whatsapp_number=coalesce((SELECT whatsapp_number FROM printex_keep.customer_service LIMIT 1),'');

 DROP SCHEMA printex_keep CASCADE;
END $$;

-- ===== Cek hasil =====
SELECT p.full_name AS nama, p.role, p.is_active AS aktif, u.email
FROM public.profiles p JOIN auth.users u ON u.id=p.id ORDER BY p.role, p.full_name;
